import { t, locale, setLocale, bilingual, contentText, weekday, dateLocale, initLocale } from './i18n.js';

const $=(s,r=document)=>r.querySelector(s);
const main=$('#main'), nav=$('#bottom-nav'), pageTitle=$('#page-title'), churchName=$('#church-name'), logoutBtn=$('#logout-btn'), notificationsBtn=$('#notifications-btn');
const state={bootstrap:null,me:null,visitor:false,tab:'home',songs:null,cache:new Map(),csrf:null};

function l(en,es){return locale()==='en'?en:es;}
function esc(v=''){return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function fmtDate(iso){return new Intl.DateTimeFormat(dateLocale(),{weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(new Date(`${iso}T12:00:00`));}
function fmtTime(tm){const [h,m]=String(tm||'00:00').split(':').map(Number);return new Intl.DateTimeFormat(dateLocale(),{hour:'numeric',minute:'2-digit'}).format(new Date(2020,0,1,h,m));}
function localError(data,status){const map={AUTH_REQUIRED:'error.authentication',ACCESS_DENIED:'error.access',ADMIN_REQUIRED:'error.admin',OWNER_REQUIRED:'error.owner',ASSIGNMENT_NOT_FOUND:'error.assignmentNotFound',ASSIGNMENT_NOT_YOURS:'error.assignmentNotYours',SONG_ASSIGNMENT_ONLY:'error.songAssignmentOnly',INVALID_SONGS:'error.invalidSongs',DUPLICATE_SERVICE_SONGS:'error.duplicateServiceSongs'};return data?.code&&map[data.code]?t(map[data.code]):(data?.error||t('error.requestFailed',{status}));}
async function api(url,opt={},_retry=true){const method=String(opt.method||'GET').toUpperCase();const csrf=(state.csrf&&['POST','PUT','PATCH','DELETE'].includes(method))?{'X-CSRF-Token':state.csrf}:{};const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json','X-Locale':locale(),...csrf,...(opt.headers||{})},...opt});const text=await r.text();let data={};try{data=text?JSON.parse(text):{};}catch{data={error:text};}if(!r.ok&&r.status===403&&data?.code==='CSRF_FAILED'&&_retry){try{const meResp=await fetch('/api/auth/me',{credentials:'same-origin',headers:{'X-Locale':locale()}});if(meResp.ok){const me=await meResp.json();state.me=me;state.csrf=me.csrfToken||null;}else{state.me=null;state.csrf=null;}return api(url,opt,false);}catch{state.csrf=null;}}if(!r.ok){if(r.status===401&&data?.code==='AUTH_REQUIRED'){state.me=null;state.csrf=null;}throw new Error(localError(data,r.status));}return data;}
async function cachedApi(url,ttlMs=30000){const key=`${locale()}|${url}`;const hit=state.cache.get(key);if(hit&&hit.expiresAt>Date.now())return hit.value;const value=await api(url);state.cache.set(key,{value,expiresAt:Date.now()+ttlMs});return value;}
function clearClientCache(){state.cache.clear();}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.remove('hidden');setTimeout(()=>el.classList.add('hidden'),2800);}
function modal(html,extraClass=''){ $('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal ${esc(extraClass)}"><div class="modal-handle"></div>${html}</div></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target===e.currentTarget)closeModal();}); }
function closeModal(){$('#modal-root').innerHTML='';}

function themeMode(){return localStorage.getItem('church-theme')||'system';}
function applyTheme(mode=themeMode(),persist=true){if(persist)localStorage.setItem('church-theme',mode);const dark=mode==='dark'||(mode==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';$('#theme-color')?.setAttribute('content',dark?'#08111f':'#f7f3ec');$('#theme-btn').textContent=dark?'☀':'☾';$('#theme-btn').title=dark?t('common.light'):t('common.dark');}
function toggleTheme(){const dark=document.documentElement.dataset.theme==='dark';applyTheme(dark?'light':'dark');savePreferences().catch(()=>{});}
matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(themeMode()==='system')applyTheme('system',false);});
applyTheme();
if('serviceWorker' in navigator)navigator.serviceWorker.register('/service-worker.js').catch(()=>{});


let nativePushInitialized=false;
async function initNativePush(){
  if(nativePushInitialized||!state.me?.member)return;
  const cap=window.Capacitor,Push=cap?.Plugins?.PushNotifications;
  if(!Push||!(cap.isNativePlatform?.()??true))return;
  nativePushInitialized=true;
  try{
    await Push.removeAllListeners?.();
    await Push.addListener('registration',async token=>{try{await api('/api/member/push-devices',{method:'POST',body:JSON.stringify({token:token.value,platform:'android',deviceName:navigator.userAgent.slice(0,100)})});}catch(e){console.warn('Push token registration failed',e);}});
    await Push.addListener('registrationError',err=>console.warn('Native push registration error',err));
    await Push.addListener('pushNotificationReceived',notification=>{toast(notification?.title||t('notifications.title'));refreshNotificationBadge();});
    await Push.addListener('pushNotificationActionPerformed',action=>{const data=action?.notification?.data||{};const route=data.route||'';if(route==='schedule'||String(data.type||'').startsWith('assignment'))state.tab='schedule';else if(route==='church'||data.type==='announcement')state.tab='church';else if(route==='petitions')state.tab='petitions';else if(route==='admin-content'&&isAdmin()){location.href='/admin';return;}else state.tab='home';renderApp();});
    let permission=await Push.checkPermissions();
    if(permission.receive==='prompt')permission=await Push.requestPermissions();
    if(permission.receive==='granted')await Push.register();
  }catch(e){nativePushInitialized=false;console.warn('Native push initialization failed',e);}
}

function groups(){return state.me?.member?.groups||[];}
function isWorship(){return groups().includes('worship');}
function isMember(){return groups().includes('members');}
function canSeePrograms(){return !!state.me&&(isMember()||isWorship());}
function isAdmin(){return state.me?.member?.adminAccess||state.me?.user?.adminAccess||state.me?.user?.churchAdministrator;}

function applyBranding(){const church=state.bootstrap?.church||{};const name=locale()==='en'?(church.churchNameEn||church.churchName):(church.churchNameEs||church.churchName);churchName.textContent=name||'Church';const logo=church.logoUrl||'';const logoEl=$('#header-logo');if(logoEl){if(logo){logoEl.src=logo;logoEl.classList.remove('hidden');}else logoEl.classList.add('hidden');}document.documentElement.style.setProperty('--accent',church.accentColor||'#2563eb');document.title=`${name||'Westbury'} Church Hub`;}
function bindHeaderControls(){const lang=$('#language-btn'),theme=$('#theme-btn');if(lang){lang.textContent=locale()==='es'?'ES':'EN';lang.title=t('common.language');lang.onclick=()=>{setLocale(locale()==='es'?'en':'es');savePreferences().catch(()=>{});renderCurrent();};}if(theme)theme.onclick=toggleTheme;logoutBtn.setAttribute('aria-label',t('common.signout'));}
async function savePreferences(){if(!state.me?.member)return;await api('/api/member/preferences',{method:'PUT',body:JSON.stringify({locale:locale(),theme:themeMode()})});}

async function init(){
  state.bootstrap=await api('/api/public/bootstrap');
  initLocale(state.bootstrap.church?.defaultLocale||'es');
  const setup=await api('/api/setup/status');
  if(!setup.ownerConfigured){applyBranding();bindHeaderControls();renderSetup(setup);return;}
  try{state.me=await api('/api/auth/me');state.csrf=state.me.csrfToken||null;}catch{}
  state.csrf=state.me?.csrfToken||state.csrf;if(state.me?.member?.preferences?.locale)setLocale(state.me.member.preferences.locale,false);
  if(state.me?.member?.preferences?.theme)applyTheme(state.me.member.preferences.theme);
  state.bootstrap=await api('/api/public/bootstrap');
  applyBranding();bindHeaderControls();
  if(!state.me&&!state.visitor){renderLogin();return;}
  renderApp();
  initNativePush().catch(()=>{});
}


async function refreshNotificationBadge(){
  if(!notificationsBtn)return;
  notificationsBtn.classList.toggle('hidden',!state.me);
  if(!state.me)return;
  try{const rows=await api('/api/member/notifications');const unread=rows.filter(x=>x.status!=='read').length;const badge=$('#notification-count');if(badge){badge.textContent=String(unread);badge.classList.toggle('hidden',unread===0);}notificationsBtn.onclick=()=>openNotifications(rows);}catch{}
}
function openNotifications(rows=[]){
  modal(`<div class="modal-header"><h2>${t('notifications.title')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><div class="stack">${rows.length?rows.map(n=>`<button class="card flat notification-row" data-notification="${esc(n.id)}" style="text-align:left"><div class="row between"><strong>${esc(n.title||t('notifications.title'))}</strong><span class="tiny muted">${esc(String(n.createdAt||'').replace('T',' ').slice(0,16))}</span></div><div class="small">${esc(n.message||'')}</div>${n.status!=='read'?`<div class="tiny" style="margin-top:5px">${t('notifications.unread')}</div>`:''}</button>`).join(''):`<div class="empty">${t('notifications.empty')}</div>`}</div>`);
  $('#close-modal').onclick=closeModal;
  document.querySelectorAll('[data-notification]').forEach(b=>b.onclick=async()=>{try{await api(`/api/member/notifications/${encodeURIComponent(b.dataset.notification)}/read`,{method:'PUT'});b.querySelector('.tiny:last-child')?.remove();refreshNotificationBadge();}catch{}});
}

function renderSetup(setup){nav.classList.add('hidden');logoutBtn.classList.add('hidden');pageTitle.textContent=t('setup.title');const church=state.bootstrap?.church||{};main.innerHTML=`<div class="login-wrap"><div class="brand-hero">${church.logoUrl?`<img class="brand-hero-logo" src="${esc(church.logoUrl)}" alt="">`:''}<h2>${esc(t('setup.heading'))}</h2><p class="muted">${esc(t('setup.body'))}</p></div><form id="setup-form" class="card stack"><div class="field"><label>${t('setup.code')}</label><input class="input" name="bootstrapCode" autocomplete="one-time-code" required></div><div class="field"><label>${t('setup.adminUsername')}</label><input class="input" name="username" value="${esc(setup.initialOwnerUsername||'churchadmin')}" required></div><div class="field"><label>${t('common.password')}</label><input class="input" name="password" type="password" minlength="12" required><span class="tiny muted">${t('setup.passwordHint')}</span></div><div class="field"><label>${t('setup.nameOnly')}</label><input class="input" name="fullName"></div><button class="btn full">${t('setup.create')}</button></form></div>`;$('#setup-form').onsubmit=async e=>{e.preventDefault();try{const setupResult=await api('/api/setup/owner',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.csrf=setupResult.csrfToken||null;toast(t('setup.created'));location.reload();}catch(err){toast(err.message);}};}

function renderLogin(){nav.classList.add('hidden');logoutBtn.classList.add('hidden');pageTitle.textContent=t('login.welcome');const church=state.bootstrap?.church||{};const displayName=locale()==='en'?(church.churchNameEn||church.churchName):(church.churchNameEs||church.churchName);main.innerHTML=`<div class="login-wrap"><div class="brand-hero">${church.logoUrl?`<img class="brand-hero-logo" src="${esc(church.logoUrl)}" alt="${esc(displayName||'')}">`:''}<h2>${esc(displayName||'Church')}</h2><p class="muted">${t('login.prompt')}</p></div><form id="login-form" class="card stack"><div class="field"><label>${t('common.username')}</label><input class="input" name="username" autocomplete="username" required></div><div class="field"><label>${t('common.password')}</label><input class="input" name="password" type="password" autocomplete="current-password" required></div><button class="btn full">${t('login.signin')}</button><button type="button" class="btn secondary full" id="visitor-btn">${t('login.visitor')}</button><div class="login-request-row"><span>${t('login.noAccount')}</span><button type="button" class="link-button" id="request-access-btn">${t('login.requestAccess')}</button></div></form></div>`;$('#login-form').onsubmit=async e=>{e.preventDefault();try{state.me=await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.csrf=state.me.csrfToken||null;if(state.me?.member?.preferences?.locale)setLocale(state.me.member.preferences.locale,false);if(state.me?.member?.preferences?.theme)applyTheme(state.me.member.preferences.theme);state.bootstrap=await api('/api/public/bootstrap');applyBranding();renderApp();initNativePush().catch(()=>{});setTimeout(maybePromptContact,250);}catch(err){toast(err.message);}};$('#visitor-btn').onclick=()=>{state.visitor=true;renderApp();};$('#request-access-btn')?.addEventListener('click',openAccessRequestModal);}

function navItems(){if(state.visitor)return[{id:'home',ico:'🏠',label:t('common.home')},{id:'church',ico:'⛪',label:t('common.church')},{id:'connect',ico:'🤝',label:t('common.connect')}];const items=[{id:'home',ico:'🏠',label:t('common.home')}];if(canSeePrograms())items.push({id:'schedule',ico:'📅',label:t('common.schedule')});if((state.me?.member?.childrenWorkerRoles||[]).length)items.push({id:'childcare',ico:'🧸',label:l('Care','Cuidado')});items.push({id:'church',ico:'⛪',label:t('common.church')});if(isMember())items.push({id:'petitions',ico:'🙏',label:t('common.petitions')});items.push({id:'profile',ico:'👤',label:t('common.profile')});return items;}
function renderNav(){nav.classList.remove('hidden');nav.innerHTML=navItems().map(i=>`<button class="nav-btn ${state.tab===i.id?'active':''}" data-tab="${i.id}"><span class="ico">${i.ico}</span>${esc(i.label)}</button>`).join('');nav.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;renderApp();});}
function churchTodayISO(){const tz=state.bootstrap?.church?.timezone||'America/Chicago';const parts=new Intl.DateTimeFormat('en-US',{timeZone:tz,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=t=>parts.find(x=>x.type===t)?.value;return `${get('year')}-${get('month')}-${get('day')}`;}
function relativeDateLabel(iso){const a=Date.parse(`${churchTodayISO()}T00:00:00Z`),b=Date.parse(`${iso}T00:00:00Z`);const diff=Math.round((b-a)/86400000);if(diff<0)return t('date.past');if(diff===0)return t('date.today');if(diff===1)return t('date.tomorrow');if(diff>=2&&diff<=6)return t('date.thisWeek');if(diff>=7&&diff<=13)return t('date.nextWeek');return t('date.upcoming');}
function dateParts(iso){const d=new Date(`${iso}T12:00:00`);return {month:new Intl.DateTimeFormat(dateLocale(),{month:'short'}).format(d).replace('.','').toUpperCase(),day:new Intl.DateTimeFormat(dateLocale(),{day:'2-digit'}).format(d),weekday:new Intl.DateTimeFormat(dateLocale(),{weekday:'long'}).format(d)};}
function dateTileHtml(iso){const d=dateParts(iso);return `<div class="date-tile"><span>${esc(d.month)}</span><strong>${esc(d.day)}</strong></div>`;}
function assignmentName(a){return bilingual(a.ministry)||((locale()==='en'?(a.programLabelsEn||a.programLabels):(a.programLabels||[]))[0]||'');}
function unavailabilitySummary(){const ranges=(state.me?.member?.unavailability||[]).filter(r=>r?.from&&r?.to).sort((a,b)=>String(a.from).localeCompare(String(b.from)));const today=churchTodayISO();const upcoming=ranges.filter(r=>r.to>=today).slice(0,2);return upcoming;}
function unavailabilityCard(){if(!isWorship())return '';const upcoming=unavailabilitySummary();return `<div class="availability-quick"><div class="availability-icon">◷</div><div class="grow"><strong>${t('home.availabilityTitle')}</strong><span>${upcoming.length?upcoming.map(r=>`${fmtDate(r.from)}${r.to!==r.from?` – ${fmtDate(r.to)}`:''}`).join(' · '):t('home.availabilityPrompt')}</span></div><button class="btn availability-btn" id="quick-unavailability">${upcoming.length?t('home.manageAvailability'):t('home.addUnavailableDates')}</button></div>`;}
function openUnavailabilityModal(){modal(`<div class="modal-header"><div><div class="eyebrow">${t('profile.unavailability')}</div><h2>${t('home.addUnavailableDates')}</h2></div><button class="icon-btn compact" id="close-modal">×</button></div><div class="availability-note">✓ ${t('profile.unavailabilityHelp')}</div><form id="quick-unav-form" class="stack"><div class="date-field-grid"><div class="field"><label>${t('common.from')}</label><input class="input" type="date" name="from" required></div><div class="field"><label>${t('common.to')}</label><input class="input" type="date" name="to" required></div></div><div class="field"><label>${t('common.note')} (${t('common.optional')})</label><input class="input" name="note"></div><button class="btn full">${t('profile.saveUnavailability')}</button></form>`);$('#close-modal').onclick=closeModal;$('#quick-unav-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/member/unavailability',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});clearClientCache();state.me=await api('/api/auth/me');toast(r.affected?t('profile.unavailabilityReassigned',{count:r.affected}):t('profile.unavailabilitySaved'));closeModal();renderHome();}catch(err){toast(err.message);}};}
function renderCurrent(){applyBranding();bindHeaderControls();if(!state.me&&!state.visitor)return renderLogin();renderApp();}
function renderApp(){logoutBtn.classList.toggle('hidden',!state.me);refreshNotificationBadge();logoutBtn.onclick=async()=>{await api('/api/auth/logout',{method:'POST'}).catch(()=>{});state.me=null;state.visitor=false;state.tab='home';clearClientCache();state.bootstrap=await api('/api/public/bootstrap').catch(()=>state.bootstrap);renderLogin();};renderNav();const labels={home:t('common.home'),schedule:t('common.schedule'),church:t('common.church'),petitions:t('common.petitions'),profile:t('common.profile'),connect:t('common.connect'),children:l("Children","Niños"),childcare:l('Nursery / Toddlers','Nursery / Toddlers')};pageTitle.textContent=labels[state.tab]||t('common.home');if(state.tab==='home'){renderHome();setTimeout(injectChildrenHome,0);return;}if(state.tab==='schedule')return renderSchedule();if(state.tab==='church')return renderChurch();if(state.tab==='petitions')return renderPetitions();if(state.tab==='profile')return renderProfile();if(state.tab==='connect')return renderConnect();if(state.tab==='children')return renderChildren();if(state.tab==='childcare')return renderChildCarePortal();}

async function renderHome(){const services=state.bootstrap.services||[];const church=state.bootstrap.church||{};const displayName=locale()==='en'?(church.churchNameEn||church.churchName):(church.churchNameEs||church.churchName);let next='';let nextAssignment=null;if(state.me&&isWorship()){try{const assignments=await cachedApi('/api/member/assignments',30000);nextAssignment=assignments[0]||null;if(nextAssignment){const a=nextAssignment,isSongs=a.canSelectSongs,name=assignmentName(a),count=a.songs?.length||0;next=`<div class="next-assignment-card ${isSongs?'songs-assignment':''}"><div class="assignment-hero-top">${dateTileHtml(a.dateISO)}<div class="grow"><span class="context-chip">${esc(relativeDateLabel(a.dateISO))}</span><div class="next-service-name">${esc(bilingual(a.service))}</div><div class="next-service-time">${esc(dateParts(a.dateISO).weekday)} · ${fmtTime(a.service?.startTime)}</div></div></div><div class="your-assignment-label">${t('schedule.assignmentDetails')}</div><div class="assignment-callout"><span class="assignment-icon">${isSongs?'♫':'✓'}</span><div><strong>${esc(name)}</strong><span>${isSongs?t('schedule.youAreServingSongs'):t('schedule.youAreServing',{ministry:name})}</span></div></div>${isSongs?`<div class="song-action-state ${count?'done':'needs'}"><span>${count?'✓':'!'}</span><div><strong>${count?t('schedule.songCount',{count}):t('schedule.songsNeedAttention')}</strong><small>${count?t('schedule.songsSelected'):t('home.songAction')}</small></div></div><button class="btn full ${count?'secondary':''}" id="home-song-select">♫ ${count?t('schedule.editSongs'):t('schedule.chooseSongsNow')}</button>`:`<button class="btn secondary full" id="home-schedule">${t('common.view')} ${t('common.schedule')}</button>`}</div>`;}else next=`<div class="card friendly-empty"><span class="empty-icon">✓</span><div><strong>${t('home.noAssignments')}</strong><p class="muted small">${t('home.clear')}</p></div></div>`;}catch{}}
main.innerHTML=`<div class="home-welcome"><div class="home-brand-glow"></div>${church.logoUrl?`<img class="brand-hero-logo" src="${esc(church.logoUrl)}" alt="${esc(displayName||'')}">`:''}<div><div class="eyebrow">${state.me?t('home.goodToSee'):t('home.welcome')}</div><h2>${esc(state.me?.member?.fullName||displayName||'Church')}</h2><span class="home-church-name">${esc(displayName||'')}</span></div></div>${state.me?unavailabilityCard():''}${next}<div class="section-title"><h3>${t('home.usualServices')}</h3></div><div class="service-strip">${services.map(s=>`<div class="mini-service-card"><span>${esc(weekday(s.recurrence?.weekday||0))}</span><strong>${esc(bilingual(s))}</strong><b>${fmtTime(s.startTime)}</b></div>`).join('')}</div><div class="section-title"><h3>${t('home.latestNews')}</h3><button class="btn ghost" id="home-church">${t('home.seeAll')}</button></div>${contentCards((state.bootstrap.content||[]).filter(x=>x.kind==='announcement').slice(0,2))}`;$('#home-schedule')?.addEventListener('click',()=>{state.tab='schedule';renderApp();});$('#home-song-select')?.addEventListener('click',()=>openSongSelector(nextAssignment.id,nextAssignment));$('#home-church')?.addEventListener('click',()=>{state.tab='church';renderApp();});$('#quick-unavailability')?.addEventListener('click',openUnavailabilityModal);}


function mapHref(address){const q=encodeURIComponent(address||'');const ua=navigator.userAgent||'';if(/iPhone|iPad|iPod/i.test(ua))return `maps://?q=${q}`;if(/Android/i.test(ua))return `geo:0,0?q=${q}`;return `https://www.google.com/maps/search/?api=1&query=${q}`;}
function contentCards(items){if(!items.length)return `<div class="card empty">${t('home.nothingNew')}</div>`;return `<div class="stack content-feed">${items.map(x=>{const ct=String(x.attachment?.contentType||'').toLowerCase(),isImage=['image/jpeg','image/png'].includes(ct);return `<article class="content-card"><div class="content-card-top"><span class="content-kind ${x.kind==='bulletin'?'bulletin':''}">${x.kind==='bulletin'?'▤':'✦'} ${esc(x.kind==='bulletin'?t('church.bulletin'):t('church.announcement'))}</span><span class="tiny muted">${x.publishedAt?fmtDate(x.publishedAt.slice(0,10)):''}</span></div><h3>${esc(contentText(x,'title'))}</h3>${contentText(x,'body')?`<p>${esc(contentText(x,'body'))}</p>`:''}${x.address?`<a class="attachment-download map-link" href="${esc(mapHref(x.address))}"><span class="attachment-icon">⌖</span><span class="grow"><strong>${esc(x.address)}</strong><small>${t('common.address')}</small></span><span>›</span></a>`:''}${isImage?`<img class="announcement-image" src="/api/public/files/${encodeURIComponent(x.id)}" alt="${esc(contentText(x,'title'))}" loading="lazy">`:''}${x.attachment?`<a class="attachment-download" href="/api/public/files/${encodeURIComponent(x.id)}" target="_blank" download><span class="attachment-icon">${isImage?'▧':'PDF'}</span><span class="grow"><strong>${t('church.download')}</strong><small>${t('church.downloadAttachment')}</small></span><span>↓</span></a>`:''}</article>`;}).join('')}</div>`;}

function songsHtml(songs=[]){if(!songs.length)return '';return `<div class="selected-songs">${songs.map(s=>`<div class="song-line"><strong>${esc(s.number||'♪')}</strong><span>${esc(locale()==='en'?(s.titleEn||s.titleEs||s.title):(s.titleEs||s.title||s.titleEn))}</span></div>`).join('')}</div>`;}

async function renderSchedule(){if(!canSeePrograms()){state.tab='home';return renderApp();}main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const programsPromise=cachedApi('/api/member/programs',30000);const assignmentsPromise=isWorship()?cachedApi('/api/member/assignments',30000):Promise.resolve([]);const [assignments,programs]=await Promise.all([assignmentsPromise,programsPromise]);let own='';if(isWorship())own=`<div class="section-title"><div><div class="eyebrow">${t('schedule.assignmentDetails')}</div><h3>${t('schedule.myAssignments')}</h3></div></div>${assignments.length?`<div class="stack assignment-stack">${assignments.map(a=>{const isSongs=a.canSelectSongs,count=a.songs?.length||0,name=assignmentName(a);return `<div class="my-assignment-card ${isSongs?'songs-assignment':''}"><div class="assignment-hero-top">${dateTileHtml(a.dateISO)}<div class="grow"><span class="context-chip">${esc(relativeDateLabel(a.dateISO))}</span><div class="next-service-name">${esc(bilingual(a.service))}</div><div class="next-service-time">${esc(dateParts(a.dateISO).weekday)} · ${fmtTime(a.service?.startTime)}</div></div></div><div class="assignment-callout compact-callout"><span class="assignment-icon">${isSongs?'♫':'✓'}</span><div><strong>${esc(name)}</strong><span>${isSongs?t('schedule.youAreServingSongs'):t('schedule.youAreServing',{ministry:name})}</span></div></div>${isSongs?`<div class="song-action-state ${count?'done':'needs'}"><span>${count?'✓':'!'}</span><div><strong>${count?t('schedule.songCount',{count}):t('schedule.songsNeedAttention')}</strong><small>${count?t('schedule.songsSelected'):t('home.songAction')}</small></div></div>${songsHtml(a.songs)}<button class="btn full song-select-btn" data-assignment="${esc(a.id)}">♫ ${count?t('schedule.editSongs'):t('schedule.chooseSongsNow')}</button>`:''}<button class="btn secondary full replacement-btn" data-assignment="${esc(a.id)}">${t('schedule.requestReplacement')}</button></div>`;}).join('')}</div>`:`<div class="card empty">${t('schedule.noAssignments')}</div>`}`;
main.innerHTML=`${own}<div class="section-title program-section-title"><div><div class="eyebrow">${t('schedule.program')}</div><h3>${t('schedule.programs')}</h3></div></div>${programs.length?programs.map(programCard).join(''):`<div class="card empty">${t('schedule.noPrograms')}</div>`}`;main.querySelectorAll('.replacement-btn').forEach(b=>b.onclick=async()=>{const ok=await confirmAction(t('schedule.replacementConfirm'));if(!ok)return;try{b.disabled=true;const r=await api(`/api/member/replacement/${encodeURIComponent(b.dataset.assignment)}`,{method:'POST'});clearClientCache();toast(r.penaltyEligible?t('schedule.replacementCurrent'):t('schedule.replacementNoPenalty'));renderSchedule();}catch(e){toast(e.message);b.disabled=false;}});main.querySelectorAll('.song-select-btn').forEach(b=>b.onclick=()=>openSongSelector(b.dataset.assignment,assignments.find(a=>a.id===b.dataset.assignment)));bindShareButtons(programs);}catch(e){main.innerHTML=`<div class="card attention">${esc(e.message)}</div>`;}}

function programCard(p){const open=Number(p.readiness?.openAssignments??((p.items||[]).some(i=>i.assignees.some(a=>!a.memberId))?1:0)),missingSongs=Number(p.readiness?.missingSongs||0),ready=p.readiness?.ready??(open===0&&missingSongs===0);const dp=dateParts(p.dateISO);const status=ready?`<span class="badge success">✓ ${t('common.ready')}</span>`:missingSongs&&!open?`<span class="badge warn">♫ ${t('schedule.needsSongs')}</span>`:`<span class="badge warn">${t('schedule.needsAttention')}</span>`;return `<div class="card service-card modern-program ${ready?'program-ready':'program-incomplete'}"><div class="program-date-band">${dateTileHtml(p.dateISO)}<div class="grow"><span class="context-chip">${esc(relativeDateLabel(p.dateISO))}</span><div class="service-name">${esc(bilingual(p.service)||p.serviceId)}</div><div class="muted small">${esc(dp.weekday)} · ${fmtTime(p.startTime)}</div></div>${status}</div>${missingSongs?`<div class="program-warning-strip">♫ ${t('schedule.missingSongAssignments',{count:missingSongs})}</div>`:''}<div class="program-lines">${(p.items||[]).map(i=>`<div class="assignment"><div><div class="assignment-label">${esc(bilingual(i))}</div>${i.assignees.map(a=>`<div class="assignment-name">${esc(a.fullName==='Unfilled'?t('share.unfilled'):a.fullName)}</div>${i.linked?'':songsHtml(a.songs)}`).join('')}</div></div>`).join('')}</div><div class="share-actions program-share"><button class="btn secondary share-native" data-program="${esc(p.id)}">↗ ${t('common.share')}</button><button class="btn secondary share-wa" data-program="${esc(p.id)}">WhatsApp</button><button class="btn secondary share-sms" data-program="${esc(p.id)}">${t('common.text')}</button></div></div>`;}

async function openSongSelector(assignmentId,assignment){try{
  const context=await api(`/api/member/assignments/${encodeURIComponent(assignmentId)}/song-options`);
  state.songs=context.songs||[];
  const unavailable=new Set(context.usedSongIds||[]), selected=new Set(assignment?.songIds||assignment?.songs?.map(s=>s.id)||[]);let view='all',filter='';
  const titleFor=s=>locale()==='en'?(s.titleEn||s.titleEs||s.title):(s.titleEs||s.title||s.titleEn);
  const ordered=[...state.songs].sort((a,b)=>(Number(a.number)||9999)-(Number(b.number)||9999)||titleFor(a).localeCompare(titleFor(b)));
  const updateCounts=()=>{const c=selected.size;$('#song-selected-count')&&($('#song-selected-count').textContent=String(c));$('#song-selected-count-footer')&&($('#song-selected-count-footer').textContent=t('schedule.selectedCount',{count:c}));const save=$('#save-song-selection');if(save)save.textContent=t('schedule.saveSelected',{count:c});};
  const draw=()=>{const q=filter.toLowerCase().trim();const list=ordered.filter(s=>(view==='all'||selected.has(s.id))&&(!q||String(s.number||'').toLowerCase().includes(q)||String(s.titleEs||s.title||'').toLowerCase().includes(q)||String(s.titleEn||'').toLowerCase().includes(q)));$('#song-choice-list').innerHTML=list.map(s=>{const blocked=unavailable.has(s.id)&&!selected.has(s.id);return `<label class="song-choice ${selected.has(s.id)?'selected':''} ${blocked?'unavailable':''}"><input type="checkbox" value="${esc(s.id)}" ${selected.has(s.id)?'checked':''} ${blocked?'disabled':''}><span class="song-number">${esc(s.number||'♪')}</span><span class="grow"><strong>${esc(titleFor(s))}</strong>${blocked?`<small>${t('schedule.alreadyUsedService')}</small>`:''}</span><span class="song-check">✓</span></label>`;}).join('')||`<div class="empty">${t('content.noSongs')}</div>`;$('#song-choice-list').querySelectorAll('input:not(:disabled)').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.value):selected.delete(c.value);updateCounts();if(view==='selected')draw();else c.closest('.song-choice')?.classList.toggle('selected',c.checked);});updateCounts();};
  const history=(context.history||[]).map(h=>{const conflict=(h.songIds||[]).some(id=>unavailable.has(id));const names=(h.songs||[]).map(s=>`${s.number?`${s.number}. `:''}${titleFor(s)}`).join(' · ');return `<button type="button" class="history-set" data-history="${esc(h.assignmentId)}" ${conflict?'disabled':''}><strong>${esc(fmtDate(h.dateISO))}</strong><span>${esc(names)}</span>${conflict?`<span> · ${t('schedule.historyConflict')}</span>`:''}</button>`;}).join('');
  const service=bilingual(assignment?.service)||'',dp=assignment?.dateISO?dateParts(assignment.dateISO):null;
  modal(`<div class="song-picker-shell"><div class="song-picker-head"><div><span class="context-chip">♫ ${t('schedule.assignmentDetails')}</span><h2>${t('schedule.chooseSongs')}</h2><p>${esc(service)}${dp?` · ${esc(dp.weekday)} ${fmtDate(assignment.dateISO)} · ${fmtTime(assignment.service?.startTime)}`:''}</p></div><button class="icon-btn compact" id="close-modal">×</button></div>${history?`<div><h3>${t('schedule.pastSelections')}</h3><p class="tiny muted">${t('schedule.pastSelectionsHelp')}</p><div class="song-history">${history}</div></div>`:''}<div class="song-picker-tools"><input class="input" id="song-filter" placeholder="${esc(t('schedule.searchSongs'))}" inputmode="search"><div class="song-view-tabs"><button class="pill active" data-song-view="all">${t('schedule.allSongs')}</button><button class="pill" data-song-view="selected">${t('schedule.selectedOnly')} <span id="song-selected-count">${selected.size}</span></button></div></div><div id="song-choice-list" class="song-list song-picker-list"></div><div class="song-picker-footer"><div class="selected-summary"><span>♫</span><strong id="song-selected-count-footer">${t('schedule.selectedCount',{count:selected.size})}</strong></div><div class="song-picker-actions"><button class="btn secondary" id="cancel-song-selection">${t('common.cancel')}</button><button class="btn" id="save-song-selection">${t('schedule.saveSelected',{count:selected.size})}</button></div></div></div>`,'song-picker-modal');
  $('#close-modal').onclick=closeModal;$('#cancel-song-selection').onclick=closeModal;$('#song-filter').oninput=e=>{filter=e.target.value;draw();};document.querySelectorAll('[data-song-view]').forEach(b=>b.onclick=()=>{view=b.dataset.songView;document.querySelectorAll('[data-song-view]').forEach(x=>x.classList.toggle('active',x===b));draw();});
  const hmap=new Map((context.history||[]).map(h=>[h.assignmentId,h]));document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const h=hmap.get(b.dataset.history);if(!h)return;selected.clear();for(const id of h.songIds||[])if(!unavailable.has(id))selected.add(id);draw();toast(t('schedule.historyLoaded'));});
  draw();$('#save-song-selection').onclick=async()=>{try{const save=$('#save-song-selection');save.disabled=true;await api(`/api/member/assignments/${encodeURIComponent(assignmentId)}/songs`,{method:'PUT',body:JSON.stringify({songIds:[...selected]})});clearClientCache();state.songs=null;toast(t('schedule.songSaveSuccess'));closeModal();state.tab='schedule';renderSchedule();}catch(e){toast(e.message);$('#save-song-selection').disabled=false;}};
}catch(e){toast(e.message);}}
function programShareText(program){const church=state.bootstrap.church||{};const churchDisplay=locale()==='en'?(church.churchNameEn||church.churchName):(church.churchNameEs||church.churchName);const lines=[t('share.header',{church:churchDisplay||'Church',service:bilingual(program.service)||program.serviceId}),t('share.date',{date:fmtDate(program.dateISO),time:fmtTime(program.startTime)}),''];for(const item of program.items||[]){const names=item.assignees.map(a=>a.fullName==='Unfilled'?t('share.unfilled'):a.fullName).join(' & ');lines.push(`${bilingual(item)}: ${names}`);const seen=new Set();if(!item.linked)for(const a of item.assignees){for(const s of a.songs||[]){if(seen.has(s.id))continue;seen.add(s.id);const title=locale()==='en'?(s.titleEn||s.titleEs||s.title):(s.titleEs||s.title||s.titleEn);lines.push(`  • ${s.number?`${s.number}. `:''}${title}`);}}}return lines.join('\n');}
function smsHref(text){const body=encodeURIComponent(text);return /iPad|iPhone|iPod/.test(navigator.userAgent)?`sms:&body=${body}`:`sms:?body=${body}`;}
function bindShareButtons(programs){const map=new Map(programs.map(p=>[p.id,p]));main.querySelectorAll('.share-native').forEach(b=>b.onclick=async()=>{const p=map.get(b.dataset.program),text=programShareText(p);if(navigator.share){try{await navigator.share({title:`${bilingual(p.service)} - ${fmtDate(p.dateISO)}`,text});}catch{}}else{try{await navigator.clipboard.writeText(text);toast(t('schedule.copyProgram'));}catch{toast(t('schedule.shareUnavailable'));}}});main.querySelectorAll('.share-wa').forEach(b=>b.onclick=()=>{const text=programShareText(map.get(b.dataset.program));window.open(`https://wa.me/?text=${encodeURIComponent(text)}`,'_blank','noopener');});main.querySelectorAll('.share-sms').forEach(b=>b.onclick=()=>{const text=programShareText(map.get(b.dataset.program));location.href=smsHref(text);});}

function renderChurch(){const content=(state.bootstrap.content||[]).filter(x=>['announcement','bulletin'].includes(x.kind));main.innerHTML=`<div class="pill-tabs"><button class="pill active">${t('church.newsBulletin')}</button></div>${contentCards(content)}`;}
async function renderPetitions(){
  if(!isMember()){ state.tab='home'; return renderApp(); }
  main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;
  try{
    const publicPetitions=await cachedApi('/api/member/petitions',15000);
    const feed=publicPetitions.length
      ? publicPetitions.map(p=>`<article class="petition-card"><div class="petition-quote">“</div><p>${esc(p.text||'')}</p><div class="petition-meta"><span>${esc(p.memberName||t('common.member'))}</span><span>${p.createdAt?fmtDate(String(p.createdAt).slice(0,10)):''}</span></div></article>`).join('')
      : `<div class="card empty">${t('petition.noPublic')}</div>`;
    main.innerHTML=`<div class="petition-compose">
      <div class="petition-hero"><span class="petition-icon">🙏</span><div><h2>${t('petition.title')}</h2><p>${t('petition.body')}</p></div></div>
      <form id="petition-form" class="stack">
        <div class="field"><label>${t('petition.request')}</label><textarea class="textarea" name="text" required placeholder="${esc(t('petition.placeholder'))}"></textarea></div>
        <div class="visibility-picker">
          <label class="visibility-option"><input type="radio" name="visibility" value="private" checked><span class="visibility-icon">🔒</span><span><strong>${t('petition.private')}</strong><small>${t('petition.privateHelp')}</small></span></label>
          <label class="visibility-option"><input type="radio" name="visibility" value="public"><span class="visibility-icon">👥</span><span><strong>${t('petition.public')}</strong><small>${t('petition.publicHelp')}</small></span></label>
        </div>
        <button class="btn full">${t('petition.send')}</button>
      </form>
    </div>
    <div class="section-title"><div><div class="eyebrow">${t('petition.community')}</div><h3>${t('petition.publicRequests')}</h3></div></div>
    <div class="stack petition-feed">${feed}</div>`;
    $('#petition-form').onsubmit=async e=>{
      e.preventDefault();
      const f=new FormData(e.target);
      try{
        await api('/api/member/petitions',{method:'POST',body:JSON.stringify({text:f.get('text'),private:f.get('visibility')!=='public'})});
        clearClientCache();
        toast(t('petition.sent'));
        renderPetitions();
      }catch(err){ toast(err.message); }
    };
  }catch(err){ main.innerHTML=`<div class="attention">${esc(err.message)}</div>`; }
}
function confirmAction(message){return new Promise(resolve=>{modal(`<div class="modal-header"><h2>${t('schedule.requestReplacement')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><p>${esc(message)}</p><div class="button-grid"><button class="btn secondary" id="confirm-no">${t('common.cancel')}</button><button class="btn" id="confirm-yes">${t('common.yes')}</button></div>`);const done=v=>{closeModal();resolve(v)};$('#close-modal').onclick=()=>done(false);$('#confirm-no').onclick=()=>done(false);$('#confirm-yes').onclick=()=>done(true);});}
function openAccessRequestModal(){modal(`<div class="modal-header"><div><div class="eyebrow">${t('login.noAccount')}</div><h2>${t('login.requestTitle')}</h2></div><button class="icon-btn compact" id="close-modal">×</button></div><p class="muted small">${t('login.requestHelp')}</p><form id="access-request-form" class="stack"><div class="field"><label>${t('login.firstName')}</label><input class="input" name="firstName" required></div><div class="field"><label>${t('login.lastName')}</label><input class="input" name="lastName" required></div><div class="field"><label>${t('common.phone')} (${t('common.optional')})</label><input class="input" name="phone" inputmode="tel"><span class="tiny muted">${t('login.phoneHelp')}</span></div><div class="field"><label>${t('common.email')} (${t('common.optional')})</label><input class="input" name="email" type="email"><span class="tiny muted">${t('login.emailHelp')}</span></div><button class="btn full">${t('login.requestAccess')}</button></form>`);$('#close-modal').onclick=closeModal;$('#access-request-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/public/member-access-request',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});closeModal();toast(t('login.requestSent'));}catch(err){toast(err.message);}};}

async function childrenSummaryCard(){if(!state.me?.member)return '';try{const d=await api('/api/member/children');if(!d.enabled)return `<div class="card stack"><div class="row between"><div><strong>${l("Children's Check-in","Registro de niños")}</strong><div class="small muted">${l('Optional family drop-off and pickup notifications.','Registro opcional de entrega/recogida y notificaciones familiares.')}</div></div><span>👧</span></div><button class="btn secondary full" id="children-signup-home">${l('Sign up','Registrarme')}</button></div>`;return `<div class="card stack"><div class="row between"><div><strong>${l("Children's Check-in","Registro de niños")}</strong><div class="small muted">${l(`${d.children.length} child(ren) registered`,`${d.children.length} niño(s) registrado(s)`)}</div></div><span>👧</span></div><button class="btn secondary full" id="children-open-home">${l('Open children module','Abrir módulo de niños')}</button></div>`;}catch{return '';}}
async function injectChildrenHome(){const html=await childrenSummaryCard();if(!html||state.tab!=='home')return;main.insertAdjacentHTML('beforeend',html);$('#children-signup-home')?.addEventListener('click',()=>childrenEnrollmentModal(false));$('#children-open-home')?.addEventListener('click',()=>{state.tab='children';renderApp();});}
async function childrenEnrollmentModal(enabled){let d={enabled:false,notificationPreferences:{sms:true,email:true,push:true}};try{d=await api('/api/member/children');}catch{}modal(`<div class="modal-header"><h2>${l("Children's Check-in","Registro de niños")}</h2><button class="icon-btn compact" id="close-modal">×</button></div><form id="children-enroll-form" class="stack"><p class="muted small">${l('Enroll your family to use child drop-off/pickup registration and receive status notifications.','Registra a tu familia para usar entrega/recogida de niños y recibir notificaciones de estado.')}</p><label class="check-row"><input type="checkbox" name="enabled" ${d.enabled?'checked':''}> ${l('Enable Children\'s Check-in','Activar Registro de niños')}</label><label class="check-row"><input type="checkbox" name="sms" ${d.notificationPreferences?.sms!==false?'checked':''}> ${l('Text notifications','Notificaciones por texto')}</label><label class="check-row"><input type="checkbox" name="email" ${d.notificationPreferences?.email!==false?'checked':''}> ${l('Email notifications','Notificaciones por correo')}</label><label class="check-row"><input type="checkbox" name="push" ${d.notificationPreferences?.push!==false?'checked':''}> ${l('App push notifications','Notificaciones push')}</label><button class="btn full">${t('common.save')}</button></form>`);$('#close-modal').onclick=closeModal;$('#children-enroll-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await api('/api/member/children/enrollment',{method:'PUT',body:JSON.stringify({enabled:f.get('enabled')==='on',sms:f.get('sms')==='on',email:f.get('email')==='on',push:f.get('push')==='on'})});state.me=await api('/api/auth/me');closeModal();toast(l('Children settings saved','Configuración de niños guardada'));renderCurrent();};}
async function renderChildren(){if(!state.me)return;main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const d=await api('/api/member/children');if(!d.enabled){main.innerHTML=`<div class="children-hero"><div class="children-hero-art">🧸</div><div><div class="eyebrow">${l('Family ministry','Ministerio familiar')}</div><h2>${l("Children's Check-in","Registro de niños")}</h2><p>${l('A simple, secure way to manage drop-off, pickup and family notifications.','Una forma sencilla y segura de administrar entrega, recogida y notificaciones familiares.')}</p></div><button class="btn" id="children-enroll">${l('Sign up','Registrarme')}</button></div>`;$('#children-enroll').onclick=()=>childrenEnrollmentModal(false);return;}
  const cards=d.children.map(c=>{const area=c.careArea==='toddlers'?l('Toddlers','Toddlers'):l('Nursery','Nursery');const gender=c.gender==='female'?l('Girl','Niña'):c.gender==='male'?l('Boy','Niño'):l('Not specified','No especificado');return `<div class="child-card"><div class="child-card-top"><div class="child-avatar">${c.careArea==='toddlers'?'🧩':'🍼'}</div><div class="grow"><strong>${esc(c.name)}</strong><div class="child-meta"><span>${l('Age','Edad')} ${esc(c.age)}</span><span>${esc(gender)}</span><span>${esc(area)}</span></div></div><button class="icon-btn compact" data-child-edit="${esc(c.id)}">✎</button></div>${c.specialInstructions?`<div class="child-instructions"><span>★</span><div><strong>${l('Care instructions','Instrucciones de cuidado')}</strong><p>${esc(c.specialInstructions)}</p></div></div>`:''}<button class="btn full" data-child-checkin="${esc(c.id)}">✓ ${l('Check in','Registrar entrada')}</button></div>`;}).join('');
  main.innerHTML=`<div class="children-hero compact"><div class="children-hero-art">🧸</div><div class="grow"><div class="eyebrow">${l('Family ministry','Ministerio familiar')}</div><h2>${l("Children's Check-in","Registro de niños")}</h2><p>${l('Drop-off, pickup and care information in one place.','Entrega, recogida e información de cuidado en un solo lugar.')}</p></div><button class="icon-btn" id="children-settings">⚙</button></div><div class="stack child-card-grid">${cards||`<div class="card empty">${l('No children registered yet.','Aún no hay niños registrados.')}</div>`}</div><button class="btn secondary full" id="add-child">+ ${l('Add child','Agregar niño')}</button><div class="section-title"><h3>${l('Recent activity','Actividad reciente')}</h3></div><div class="stack">${(d.recentCheckIns||[]).map(r=>`<div class="card flat"><div class="row between"><strong>${esc(r.childName)}</strong><span class="badge">${esc(r.status)}</span></div><div class="tiny muted">${esc(r.checkInAt||'')}</div>${r.status==='checked_in'?`<button class="btn secondary full" data-child-pickup="${esc(r.id)}">${l('Pick up','Recoger')}</button>`:''}</div>`).join('')}</div>`;
  $('#children-settings').onclick=()=>childrenEnrollmentModal(true);$('#add-child').onclick=()=>childModal();main.querySelectorAll('[data-child-edit]').forEach(b=>b.onclick=()=>childModal(d.children.find(c=>c.id===b.dataset.childEdit)));main.querySelectorAll('[data-child-checkin]').forEach(b=>b.onclick=async()=>{try{const r=await api(`/api/member/children/${b.dataset.childCheckin}/check-in`,{method:'POST',body:'{}'});toast(`${l('Checked in. Pickup code','Entrada registrada. Código de recogida')}: ${r.pickupCode}`);renderChildren();}catch(e){toast(e.message);}});main.querySelectorAll('[data-child-pickup]').forEach(b=>b.onclick=()=>pickupModal(b.dataset.childPickup));}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
function childModal(child=null){const isEdit=Boolean(child);modal(`<div class="modal-header"><div><div class="eyebrow">${l('Children profile','Perfil infantil')}</div><h2>${isEdit?esc(child.name):l('Add child','Agregar niño')}</h2></div><button class="icon-btn compact" id="close-modal">×</button></div><form id="child-form" class="stack"><div class="child-form-banner">🧸 <span>${l('These details stay handy for Nursery/Toddler caregivers while the child is checked in.','Estos datos estarán disponibles para los cuidadores mientras el niño esté registrado.')}</span></div><div class="field"><label>${l('Child name','Nombre del niño')}</label><input class="input" name="name" value="${esc(child?.name||'')}" required></div><div class="row"><div class="field grow"><label>${l('Age','Edad')}</label><input class="input" name="age" type="number" min="0" max="25" value="${esc(child?.age??'')}" required></div><div class="field grow"><label>${l('Gender','Género')}</label><select class="select" name="gender"><option value="unspecified" ${(child?.gender||'unspecified')==='unspecified'?'selected':''}>${l('Not specified','No especificado')}</option><option value="female" ${child?.gender==='female'?'selected':''}>${l('Female','Femenino')}</option><option value="male" ${child?.gender==='male'?'selected':''}>${l('Male','Masculino')}</option><option value="other" ${child?.gender==='other'?'selected':''}>${l('Other','Otro')}</option></select></div></div><div class="field"><label>${l('Care area','Área de cuidado')}</label><div class="care-area-picker"><label><input type="radio" name="careArea" value="nursery" ${(child?.careArea||'nursery')==='nursery'?'checked':''}><span>🍼 <strong>${l('Nursery','Nursery')}</strong></span></label><label><input type="radio" name="careArea" value="toddlers" ${child?.careArea==='toddlers'?'checked':''}><span>🧩 <strong>${l('Toddlers','Toddlers')}</strong></span></label></div></div><div class="field"><label>${l('Special instructions for caregivers','Instrucciones especiales para cuidadores')}</label><textarea class="textarea" name="specialInstructions" rows="4" maxlength="1000" placeholder="${l('Feeding, comfort routine, diapering notes, allergies or other instructions the caregiver should know.','Alimentación, rutina de consuelo, pañal, alergias u otras instrucciones que el cuidador deba conocer.')}">${esc(child?.specialInstructions||'')}</textarea></div><button class="btn full">${t('common.save')}</button></form>`);$('#close-modal').onclick=closeModal;$('#child-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),payload={name:f.get('name'),age:Number(f.get('age')),gender:f.get('gender'),careArea:f.get('careArea'),specialInstructions:f.get('specialInstructions')};try{if(isEdit)await api(`/api/member/children/${encodeURIComponent(child.id)}`,{method:'PUT',body:JSON.stringify(payload)});else await api('/api/member/children',{method:'POST',body:JSON.stringify(payload)});closeModal();renderChildren();}catch(err){toast(err.message);}};}

async function renderChildCarePortal(){main.innerHTML=`<div class="card empty">${t('common.loading')}</div>`;try{const d=await api('/api/member/children-worker');const roleText=d.roles.map(r=>r==='nursery'?l('Nursery','Nursery'):l('Toddlers','Toddlers')).join(' · ');main.innerHTML=`<div class="care-portal-hero"><div><div class="eyebrow">${l('Children’s Ministry Portal','Portal del Ministerio de Niños')}</div><h2>🧸 ${esc(roleText)}</h2><p>${l('Children currently checked in for your care area. Special instructions are shown prominently.','Niños registrados actualmente en tu área. Las instrucciones especiales se muestran de forma destacada.')}</p></div><button class="btn secondary" id="care-refresh">↻ ${l('Refresh','Actualizar')}</button></div><div class="care-count">${d.children.length} ${l('checked in today','registrados hoy')}</div><div class="stack">${d.children.map(c=>`<div class="care-child-card"><div class="row between"><div class="row"><div class="child-avatar">${c.careArea==='toddlers'?'🧩':'🍼'}</div><div><h3>${esc(c.childName)}</h3><div class="small muted">${l('Age','Edad')} ${esc(c.childAge)} · ${c.childGender==='female'?l('Girl','Niña'):c.childGender==='male'?l('Boy','Niño'):l('Gender not specified','Género no especificado')}</div></div></div><span class="badge">${c.careArea==='toddlers'?l('Toddlers','Toddlers'):l('Nursery','Nursery')}</span></div><div class="parent-line"><span>👤</span><div><small>${l('Parent / Guardian','Padre / Tutor')}</small><strong>${esc(c.parentName||'')}</strong></div></div>${c.specialInstructions?`<div class="care-alert-note"><span>★</span><div><strong>${l('Special instructions','Instrucciones especiales')}</strong><p>${esc(c.specialInstructions)}</p></div></div>`:`<div class="care-no-note">✓ ${l('No special instructions on file','No hay instrucciones especiales registradas')}</div>`}<div class="tiny muted">${l('Checked in','Entrada')}: ${esc(String(c.checkInAt||'').replace('T',' ').slice(0,16))}</div><button class="btn full parent-alert-btn" data-parent-alert="${esc(c.id)}">🔔 ${l('Alert parent to come now','Avisar al padre que venga ahora')}</button><div class="delivery-hints">${c.parentHasSms?'<span>SMS ✓</span>':''}${c.parentHasPush?'<span>Push ✓</span>':''}${c.parentHasEmail?'<span>Email ✓</span>':''}</div></div>`).join('')||`<div class="card empty">${l('No children are currently checked in for your area.','No hay niños registrados actualmente en tu área.')}</div>`}</div>`;$('#care-refresh').onclick=renderChildCarePortal;main.querySelectorAll('[data-parent-alert]').forEach(b=>b.onclick=async()=>{if(!confirm(l('Notify the parent/guardian to come to the children’s area now?','¿Notificar al padre/tutor que venga al área de niños ahora?')))return;try{const r=await api(`/api/member/children-worker/check-ins/${encodeURIComponent(b.dataset.parentAlert)}/alert`,{method:'POST',body:'{}'});toast(l(`Parent alert queued on ${r.queued} channel(s).`,`Alerta enviada por ${r.queued} canal(es).`));}catch(e){toast(e.message);}});}catch(e){main.innerHTML=`<div class="attention">${esc(e.message)}</div>`;}}
function pickupModal(id){modal(`<div class="modal-header"><h2>${l('Child pickup','Recogida del niño')}</h2><button class="icon-btn compact" id="close-modal">×</button></div><form id="pickup-form" class="stack"><div class="field"><label>${l('6-digit pickup code','Código de recogida de 6 dígitos')}</label><input class="input" name="pickupCode" inputmode="numeric" maxlength="6" required></div><button class="btn full">${l('Confirm pickup','Confirmar recogida')}</button></form>`);$('#close-modal').onclick=closeModal;$('#pickup-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api(`/api/member/children/check-ins/${encodeURIComponent(id)}/pickup`,{method:'POST',body:JSON.stringify({pickupCode:f.get('pickupCode')})});closeModal();toast(l('Pickup recorded','Recogida registrada'));renderChildren();}catch(err){toast(err.message);}};}

function maybePromptContact(){const m=state.me?.member;if(!m||(m.email&&m.phone)||sessionStorage.getItem('contact-prompt-dismissed')==='1')return;modal(`<div class="modal-header"><div><div class="eyebrow">${t('profile.contactTitle')}</div><h2>${t('profile.addContactTitle')}</h2></div><button class="icon-btn compact" id="contact-not-now">×</button></div><p class="muted small">${t('profile.addContactHelp')}</p><form id="contact-prompt-form" class="stack"><div class="field"><label>${t('common.phone')} (${t('common.optional')})</label><input class="input" name="phone" inputmode="tel" value="${esc(m.phone||'')}"><span class="tiny muted">${t('login.phoneHelp')}</span></div><div class="field"><label>${t('common.email')} (${t('common.optional')})</label><input class="input" name="email" type="email" value="${esc(m.email||'')}"><span class="tiny muted">${t('login.emailHelp')}</span></div><button class="btn full">${t('profile.saveContact')}</button><button type="button" class="btn ghost full" id="contact-later">${t('profile.notNow')}</button></form>`);const dismiss=()=>{sessionStorage.setItem('contact-prompt-dismissed','1');closeModal();};$('#contact-not-now').onclick=dismiss;$('#contact-later').onclick=dismiss;$('#contact-prompt-form').onsubmit=async e=>{e.preventDefault();try{await api('/api/member/contact',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});state.me=await api('/api/auth/me');closeModal();toast(t('profile.contactSaved'));renderCurrent();}catch(err){toast(err.message);}};}
function renderConnect(){main.innerHTML=visitorFormHtml();bindVisitorForm();}
function visitorFormHtml(){return `<div class="card"><h2>${t('visitor.title')}</h2><p class="muted small">${t('visitor.body')}</p><form id="visitor-form" class="stack"><div class="field"><label>${t('common.name')}</label><input class="input" name="fullName" required></div><div class="field"><label>${t('common.phone')}</label><input class="input" name="phone" inputmode="tel"></div><div class="field"><label>${t('common.email')}</label><input class="input" name="email" type="email"></div><div class="field"><label>${t('common.address')}</label><input class="input" name="address"></div><label class="check-row"><input type="checkbox" name="firstVisit"><span>${t('visitor.first')}</span></label><div class="field"><label>${t('visitor.prayer')}</label><textarea class="textarea" name="prayerRequest"></textarea></div><button class="btn full">${t('visitor.send')}</button></form></div>`;}
function bindVisitorForm(){const f=$('#visitor-form');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f));d.firstVisit=d.firstVisit==='on';try{await api('/api/public/visitor-contact',{method:'POST',body:JSON.stringify(d)});f.reset();toast(t('visitor.thanks'));}catch(err){toast(err.message);}};}

function renderProfile(){if(!state.me){main.innerHTML=visitorFormHtml();bindVisitorForm();return;}const m=state.me.member;const unav=isWorship()?`<div class="card stack priority-card"><h3>${t('profile.unavailability')}</h3><p class="muted small">${t('profile.unavailabilityHelp')}</p><form id="unav-form" class="stack"><div class="row"><div class="field grow"><label>${t('common.from')}</label><input class="input" type="date" name="from" required></div><div class="field grow"><label>${t('common.to')}</label><input class="input" type="date" name="to" required></div></div><div class="field"><label>${t('common.note')} (${t('common.optional')})</label><input class="input" name="note"></div><button class="btn full">${t('profile.saveUnavailability')}</button></form></div>`:'';main.innerHTML=`<div class="card stack"><div class="row"><div class="avatar">${esc((m.fullName||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</div><div><h2>${esc(m.fullName)}</h2><div class="muted small">${esc(m.email||m.phone||m.username||'')}</div></div></div><div><span class="badge">${(m.groups||[]).map(g=>g==='members'?t('common.member'):g==='worship'?t('common.worship'):esc(g)).join(' · ')}</span></div>${isAdmin()?`<a class="btn full" href="/admin/">${t('profile.adminConsole')}</a>`:''}</div>${state.me.user?.mustChangePassword?`<div class="attention"><span class="ico">!</span><div><strong>${t('profile.passwordRequired')}</strong><div class="small">${t('profile.passwordRequiredHelp')}</div></div></div>`:''}${unav}<div class="card stack"><h3>${t('profile.contactTitle')}</h3><p class="muted small">${t('profile.contactHelp')}</p><form id="contact-form" class="stack"><div class="field"><label>${t('common.phone')} (${t('common.optional')})</label><input class="input" name="phone" inputmode="tel" value="${esc(m.phone||'')}"></div><div class="field"><label>${t('common.email')} (${t('common.optional')})</label><input class="input" type="email" name="email" value="${esc(m.email||'')}"></div><div class="check-grid"><label class="check-row"><input type="checkbox" name="smsNotificationsEnabled" ${(m.notificationPreferences?.sms!==false)?'checked':''}> ${l('Text notifications','Notificaciones por texto')}</label><label class="check-row"><input type="checkbox" name="emailNotificationsEnabled" ${(m.notificationPreferences?.email!==false)?'checked':''}> ${l('Email notifications','Notificaciones por correo')}</label></div><div class="tiny muted">${l('Your phone and email stay on your profile even when a notification channel is turned off.','Tu teléfono y correo permanecen en tu perfil aunque desactives un canal de notificación.')}</div><button class="btn secondary full">${t('profile.saveContact')}</button></form></div><div class="card stack"><h3>${l("Children's Check-in","Registro de niños")}</h3><p class="muted small">${l('Manage children, drop-off/pickup enrollment and family notification preferences.','Administra niños, registro de entrega/recogida y preferencias de notificación familiar.')}</p><button class="btn secondary full" id="profile-children">${l('Manage children','Administrar niños')}</button></div>${(m.childrenWorkerRoles||[]).length?`<div class="card stack childcare-profile-card"><div class="row between"><div><div class="eyebrow">${l('Children’s Ministry','Ministerio de Niños')}</div><h3>${l('Caregiver access','Acceso de cuidador')}</h3></div><span>🧸</span></div><p class="muted small">${l('You are assigned to','Estás asignado a')}: ${(m.childrenWorkerRoles||[]).map(r=>r==='nursery'?l('Nursery','Nursery'):l('Toddlers','Toddlers')).join(' · ')}</p><button class="btn secondary full" id="profile-childcare">${l('Open caregiver portal','Abrir portal de cuidadores')}</button></div>`:''}<div class="card stack"><h3>${t('profile.security')}</h3><form id="password-form" class="stack"><div class="field"><label>${t('profile.currentPassword')}</label><input class="input" type="password" name="currentPassword" autocomplete="current-password" required></div><div class="field"><label>${t('profile.newPassword')}</label><input class="input" type="password" name="newPassword" minlength="12" autocomplete="new-password" required></div><button class="btn secondary full">${t('profile.changePassword')}</button></form></div><div class="card stack"><h3>${t('common.appearance')}</h3><div class="field"><label>${t('common.language')}</label><div class="locale-toggle"><button class="btn secondary locale-option ${locale()==='es'?'active':''}" data-locale="es">Español</button><button class="btn secondary locale-option ${locale()==='en'?'active':''}" data-locale="en">English</button></div></div><div class="field"><label>${t('common.theme')}</label><div class="theme-grid"><button class="btn secondary theme-option ${themeMode()==='system'?'active':''}" data-theme="system">${t('common.system')}</button><button class="btn secondary theme-option ${themeMode()==='light'?'active':''}" data-theme="light">${t('common.light')}</button><button class="btn secondary theme-option ${themeMode()==='dark'?'active':''}" data-theme="dark">${t('common.dark')}</button></div></div></div>`;main.querySelectorAll('[data-locale]').forEach(b=>b.onclick=async()=>{setLocale(b.dataset.locale);await savePreferences().catch(()=>{});renderCurrent();});main.querySelectorAll('[data-theme]').forEach(b=>b.onclick=async()=>{applyTheme(b.dataset.theme);await savePreferences().catch(()=>{});renderProfile();});$('#contact-form')?.addEventListener('submit',async e=>{e.preventDefault();try{(()=>{const f=new FormData(e.target),d=Object.fromEntries(f);d.smsNotificationsEnabled=f.get('smsNotificationsEnabled')==='on';d.emailNotificationsEnabled=f.get('emailNotificationsEnabled')==='on';return api('/api/member/contact',{method:'PUT',body:JSON.stringify(d)});})();state.me=await api('/api/auth/me');toast(t('profile.contactSaved'));renderProfile();}catch(err){toast(err.message);}});$('#profile-children')?.addEventListener('click',()=>{state.tab='children';renderApp();});$('#profile-childcare')?.addEventListener('click',()=>{state.tab='childcare';renderApp();});$('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();try{const r=await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();toast(t('profile.passwordChanged'));if(r.reauthenticate){state.me=null;state.csrf=null;setTimeout(()=>location.href='/',500);return;}state.me=await api('/api/auth/me');state.csrf=state.me.csrfToken||null;renderProfile();}catch(err){toast(err.message);}});$('#unav-form')?.addEventListener('submit',async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const r=await api('/api/member/unavailability',{method:'POST',body:JSON.stringify(d)});clearClientCache();toast(r.affected?t('profile.unavailabilityReassigned',{count:r.affected}):t('profile.unavailabilitySaved'));state.me=await api('/api/auth/me');renderProfile();}catch(err){toast(err.message);}});}
window.addEventListener('church:locale',()=>{if(state.bootstrap)renderCurrent();});
init().catch(e=>{main.innerHTML=`<div class="card attention">${esc(e.message)}</div>`;});
